<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
require_admin(); $adminId = (int) current_user()['id'];

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $operation = $_POST['operation'] ?? '';
    try {
        if ($operation === 'add_skill') {
            $name = trim($_POST['name'] ?? ''); $category = trim($_POST['category'] ?? ''); $description = trim($_POST['description'] ?? '');
            if ($name === '' || $category === '' || $description === '') { throw new RuntimeException('Complete every skill field.'); }
            db()->prepare('INSERT INTO skills (name, category, description) VALUES (?, ?, ?)')->execute([$name, $category, $description]); flash('success', 'Skill added.');
        } elseif ($operation === 'delete_skill') {
            $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT); if (!$id) { throw new RuntimeException('Invalid skill.'); }
            db()->prepare('DELETE FROM skills WHERE id = ?')->execute([$id]); flash('success', 'Skill removed.');
        } elseif ($operation === 'add_course') {
            $title = trim($_POST['title'] ?? ''); $provider = trim($_POST['provider'] ?? ''); $category = trim($_POST['category'] ?? ''); $description = trim($_POST['description'] ?? ''); $level = $_POST['level'] ?? ''; $duration = trim($_POST['duration'] ?? ''); $url = trim($_POST['course_url'] ?? '');
            if ($title === '' || $provider === '' || $category === '' || $description === '' || $duration === '' || !in_array($level, ['Beginner','Intermediate','Advanced'], true)) { throw new RuntimeException('Complete all required course fields.'); }
            if ($url !== '' && !filter_var($url, FILTER_VALIDATE_URL)) { throw new RuntimeException('Enter a valid course URL or leave it blank.'); }
            db()->prepare('INSERT INTO courses (title, provider, category, description, level, duration, course_url) VALUES (?, ?, ?, ?, ?, ?, ?)')->execute([$title, $provider, $category, $description, $level, $duration, $url ?: null]); flash('success', 'Course added.');
        } elseif ($operation === 'delete_course') {
            $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT); if (!$id) { throw new RuntimeException('Invalid course.'); }
            db()->prepare('DELETE FROM courses WHERE id = ?')->execute([$id]); flash('success', 'Course removed.');
        } elseif ($operation === 'change_role') {
            $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT); $role = $_POST['role'] ?? '';
            if (!$id || !in_array($role, ['student','admin'], true)) { throw new RuntimeException('Invalid user role.'); }
            if ($id === $adminId) { throw new RuntimeException('You cannot change your own administrator role.'); }
            db()->prepare('UPDATE users SET role = ? WHERE id = ?')->execute([$role, $id]); flash('success', 'User role updated.');
        }
    } catch (Throwable $e) { flash('error', $e instanceof PDOException && $e->getCode() === '23000' ? 'That record already exists or is in use.' : $e->getMessage()); }
    redirect('admin.php?tab=' . urlencode($_POST['return_tab'] ?? 'overview'));
}

$tab = $_GET['tab'] ?? 'overview'; if (!in_array($tab, ['overview','courses','skills','users'], true)) { $tab = 'overview'; }
$counts = db()->query('SELECT (SELECT COUNT(*) FROM users) AS users, (SELECT COUNT(*) FROM courses) AS courses, (SELECT COUNT(*) FROM skills) AS skills, (SELECT COUNT(*) FROM assessments) AS assessments')->fetch();
$page_title = 'Admin dashboard'; require __DIR__ . '/includes/header.php';
?>
<section class="container py-4 py-lg-5"><div class="mb-4"><p class="text-primary fw-semibold mb-1">ADMINISTRATION</p><h1 class="section-title">Manage SkillPath</h1><p class="text-secondary mb-0">Maintain the people, skills, courses, and learning catalog.</p></div>
<ul class="nav nav-pills gap-2 mb-4"><li class="nav-item"><a class="nav-link <?= $tab === 'overview' ? 'active' : '' ?>" href="admin.php?tab=overview">Overview</a></li><li class="nav-item"><a class="nav-link <?= $tab === 'courses' ? 'active' : '' ?>" href="admin.php?tab=courses">Courses</a></li><li class="nav-item"><a class="nav-link <?= $tab === 'skills' ? 'active' : '' ?>" href="admin.php?tab=skills">Skills</a></li><li class="nav-item"><a class="nav-link <?= $tab === 'users' ? 'active' : '' ?>" href="admin.php?tab=users">Users</a></li></ul>
<?php if ($tab === 'overview'): ?><div class="row g-3 mb-4"><div class="col-6 col-lg-3"><div class="card p-3"><div class="metric"><?= (int) $counts['users'] ?></div><div class="metric-label">Registered users</div></div></div><div class="col-6 col-lg-3"><div class="card p-3"><div class="metric"><?= (int) $counts['courses'] ?></div><div class="metric-label">Courses</div></div></div><div class="col-6 col-lg-3"><div class="card p-3"><div class="metric"><?= (int) $counts['skills'] ?></div><div class="metric-label">Skills</div></div></div><div class="col-6 col-lg-3"><div class="card p-3"><div class="metric"><?= (int) $counts['assessments'] ?></div><div class="metric-label">Assessments completed</div></div></div></div><div class="card p-4"><h4>Rule-based recommendations</h4><p class="text-secondary mb-3">Recommendations use a student's profile keywords, selected existing skills, career goal, and their latest assessment. Courses that develop a matched skill or assessment gap are ranked first.</p><div class="d-flex flex-wrap gap-2"><a class="btn btn-outline-primary btn-sm" href="admin.php?tab=courses">Manage courses</a><a class="btn btn-outline-primary btn-sm" href="admin.php?tab=skills">Manage skills</a><a class="btn btn-outline-primary btn-sm" href="admin.php?tab=users">Manage users</a></div></div>
<?php elseif ($tab === 'courses'): $courses = db()->query('SELECT id, title, provider, category, level, duration FROM courses ORDER BY id DESC')->fetchAll(); ?><div class="row g-4"><div class="col-xl-4"><div class="card p-4"><h4 class="mb-3">Add course</h4><form method="post"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="operation" value="add_course"><input type="hidden" name="return_tab" value="courses"><div class="mb-2"><input class="form-control" name="title" placeholder="Course title" required></div><div class="mb-2"><input class="form-control" name="provider" placeholder="Provider" required></div><div class="mb-2"><input class="form-control" name="category" placeholder="Category, e.g. Data" required></div><div class="mb-2"><select class="form-select" name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div class="mb-2"><input class="form-control" name="duration" placeholder="Duration, e.g. 6 weeks" required></div><div class="mb-2"><input class="form-control" type="url" name="course_url" placeholder="Course URL (optional)"></div><div class="mb-3"><textarea class="form-control" name="description" rows="3" placeholder="Short description" required></textarea></div><button class="btn btn-primary w-100">Add course</button></form></div></div><div class="col-xl-8"><div class="card overflow-hidden"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Course</th><th>Category</th><th>Level</th><th></th></tr></thead><tbody><?php foreach ($courses as $course): ?><tr><td><strong><?= e($course['title']) ?></strong><div class="small text-secondary"><?= e($course['provider']) ?> · <?= e($course['duration']) ?></div></td><td><?= e($course['category']) ?></td><td><?= e($course['level']) ?></td><td class="text-end"><form method="post" onsubmit="return confirm('Remove this course?')"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="operation" value="delete_course"><input type="hidden" name="return_tab" value="courses"><input type="hidden" name="id" value="<?= (int) $course['id'] ?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php elseif ($tab === 'skills'): $skills = db()->query('SELECT id, name, category, description FROM skills ORDER BY category, name')->fetchAll(); ?><div class="row g-4"><div class="col-xl-4"><div class="card p-4"><h4 class="mb-3">Add skill</h4><form method="post"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="operation" value="add_skill"><input type="hidden" name="return_tab" value="skills"><div class="mb-2"><input class="form-control" name="name" placeholder="Skill name" required></div><div class="mb-2"><input class="form-control" name="category" placeholder="Category" required></div><div class="mb-3"><textarea class="form-control" name="description" rows="3" placeholder="What will a student learn?" required></textarea></div><button class="btn btn-primary w-100">Add skill</button></form></div></div><div class="col-xl-8"><div class="card overflow-hidden"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Skill</th><th>Category</th><th></th></tr></thead><tbody><?php foreach ($skills as $skill): ?><tr><td><strong><?= e($skill['name']) ?></strong><div class="small text-secondary"><?= e($skill['description']) ?></div></td><td><?= e($skill['category']) ?></td><td class="text-end"><form method="post" onsubmit="return confirm('Remove this skill and its linked questions?')"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="operation" value="delete_skill"><input type="hidden" name="return_tab" value="skills"><input type="hidden" name="id" value="<?= (int) $skill['id'] ?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php else: $users = db()->query('SELECT id, full_name, email, role, created_at FROM users ORDER BY created_at DESC')->fetchAll(); ?><div class="card overflow-hidden"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Name</th><th>Role</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach ($users as $member): ?><tr><td><strong><?= e($member['full_name']) ?></strong><div class="small text-secondary"><?= e($member['email']) ?></div></td><td><span class="badge <?= $member['role'] === 'admin' ? 'text-bg-primary' : 'text-bg-light border text-secondary' ?>"><?= e(ucfirst($member['role'])) ?></span></td><td class="small text-secondary"><?= e(date('d M Y', strtotime($member['created_at']))) ?></td><td class="text-end"><?php if ((int) $member['id'] !== $adminId): ?><form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="operation" value="change_role"><input type="hidden" name="return_tab" value="users"><input type="hidden" name="id" value="<?= (int) $member['id'] ?>"><input type="hidden" name="role" value="<?= $member['role'] === 'admin' ? 'student' : 'admin' ?>"><button class="btn btn-sm btn-outline-primary">Make <?= $member['role'] === 'admin' ? 'student' : 'admin' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
</section>
